const $ = (id) => document.getElementById(id);
const state = { picked: new Set(), removed: new Map(), region: "", kind: "", role: "", q: "" };
const mailStates = new Map();
const mailStateMeta = {
  not_sent: { label: "Не отправлен", cls: "" },
  queued: { label: "В очереди", cls: "queued" },
  sending: { label: "Отправляется", cls: "sending" },
  sent: { label: "Запрос отправлен", cls: "sent" },
  failed: { label: "Ошибка отправки", cls: "failed" }
};

const posName = Object.fromEntries(DATA.positions.map(p => [p.id, p.name]));

/* Поставщик считается подтверждённым, когда сошлись три вещи: контакт прошёл
   проверку, компания найдена по ИНН и она закрывает хотя бы одну позицию. */
const isVerified = (s) =>
  s.conf === "high" && !!s.inn && s.covers.length > 0 &&
  !!s.reg && s.reg.status === "Действует" && s.reg.risks.length === 0;

function cleanTitle(s) {
  if (s.reg && s.reg.name) return s.reg.name;
  let t = (s.title || s.host).split(/[|—–]/)[0].replace(/\.\.\.$/, "").trim();
  if (t.length > 62) t = t.slice(0, 62).replace(/\s+\S*$/, "") + "…";
  return t || s.host;
}

function renderPositions() {
  $("positions").innerHTML = DATA.positions.map(p =>
    `<div class="pos"><b>${p.name}</b><span>${p.qty}</span></div>`).join("");
}

function renderFilters() {
  const regions = [...new Set(DATA.suppliers.map(s => s.region).filter(Boolean))].sort();
  $("fRegion").insertAdjacentHTML("beforeend",
    regions.map(r => `<option value="${r}">${r}</option>`).join(""));
}

function visible() {
  return DATA.suppliers.filter(s => {
    if (state.removed.has(s.host)) return false;
    if (state.region && s.region !== state.region) return false;
    if (state.kind && s.kind !== state.kind) return false;
    if (state.role && (!s.reg || s.reg.role !== state.role)) return false;
    if (state.q) {
      const hay = (s.host + " " + s.title).toLowerCase();
      if (!hay.includes(state.q.toLowerCase())) return false;
    }
    return true;
  });
}

function cardHtml(s) {
  const verified = isVerified(s);
  const covered = DATA.positions.map(p => s.covers.includes(p.id));
  const best = s.emails[0];
  const rest = Math.max(0, s.n_emails - 1);
  const mailState = mailStateMeta[mailStates.get(s.host) || "not_sent"] || mailStateMeta.not_sent;

  const reg = s.reg;
  const tags = [];
  if (s.region) tags.push(`<span class="tag">${s.region}</span>`);
  /* Роль в цепочке важнее формы собственности: снабженцу нужен производитель,
     а оптовик и розница — это уже наценка сверху. Берётся из ОКВЭД. */
  if (reg && reg.role === "производитель") tags.push(`<span class="tag ok">производитель</span>`);
  else if (reg && reg.role)  tags.push(`<span class="tag">${reg.role}</span>`);
  if (s.kind)   tags.push(`<span class="tag">${s.kind}</span>`);
  if (reg && reg.headcount) tags.push(`<span class="tag">${reg.headcount} ${plural(reg.headcount, "сотрудник", "сотрудника", "сотрудников")}</span>`);
  if (s.inn)    tags.push(`<span class="tag mono">ИНН ${s.inn}</span>`);
  if (!s.inn)   tags.push(`<span class="tag warn">реквизиты не найдены</span>`);
  if (s.web)    tags.push(`<span class="tag warn">сайт недоступен</span>`);

  /* Признаки риска из реестра — то, чего на сайте компании не напишут никогда. */
  const risks = (reg && reg.risks.length)
    ? `<div class="risks"><span class="lbl">Проверьте перед сделкой</span>
         ${reg.risks.map(r => `<span class="risk">${r}</span>`).join("")}</div>`
    : "";

  return `
  <article class="card ${verified ? "verified" : "maybe"} ${state.picked.has(s.host) ? "picked" : ""}" data-host="${s.host}">
    <div class="pick">
      <input type="checkbox" ${state.picked.has(s.host) ? "checked" : ""}
             aria-label="Выбрать ${s.host}" data-act="pick">
    </div>
    <div class="body">
      <h3>${cleanTitle(s)}</h3>
      <a class="dom" href="https://${s.host}" target="_blank" rel="noopener">${s.host}</a>
      <div class="meta">${tags.join("")}</div>
      <div class="reason">
        <span class="lbl">Почему в списке</span>
        ${s.snippet ? s.snippet.slice(0, 190) + (s.snippet.length > 190 ? "…" : "")
                    : "Компания найдена в поисковой выдаче по позициям заявки."}
      </div>
      ${risks}
      <div class="acts">
        <button class="btn primary mail-write-btn" data-act="compose" ${best ? "" : "disabled"}>${best ? "Написать" : "Нет email"}</button>
        <button class="btn" data-act="open">Открыть сайт</button>
        <button class="btn stop" data-act="black">В чёрный список</button>
        <button class="btn stop" data-act="irrelevant">Нерелевантно</button>
      </div>
    </div>
    <div class="side">
      <div>
        <div class="cov-head">
          <span class="lbl">Закрывает позиций</span>
          <span class="n">${s.covers.length} / ${DATA.positions.length}</span>
        </div>
        <div class="cov-bars">${covered.map(c => `<i class="${c ? "on" : ""}"></i>`).join("")}</div>
      </div>
      <div class="cov-list">
        ${DATA.positions.map(p => {
          const on = s.covers.includes(p.id);
          const short = p.name.replace("Кирпич ", "").replace("Блок ", "");
          return `<span class="${on ? "" : "no"}">${short}</span>`;
        }).join("")}
      </div>
      <div class="contacts">
        ${best
          ? `<div class="mailrow">
               <a href="mailto:${best.e}">${best.e}</a>
               ${reg && reg.confirmed.includes(best.e)
                  ? `<span class="tick" title="Адрес совпал на сайте и в реестре">✓</span>` : ""}
             </div>
             ${rest ? `<span class="more">и ещё ${rest} ${plural(rest, "адрес", "адреса", "адресов")}</span>` : ""}`
          : `<span class="more">Контакты не найдены</span>`}
        ${reg && reg.phones.length
          ? `<div class="mailrow"><a href="tel:${reg.phones[0]}">${fmtPhone(reg.phones[0])}</a></div>`
          : ""}
      </div>
      <div class="mail-status ${mailState.cls}"><span class="mail-status-dot"></span><span>${mailState.label}</span></div>
    </div>
  </article>`;
}

function fmtPhone(p) {
  const d = (p || "").replace(/\D/g, "");
  if (d.length === 11) return `+7 (${d.slice(1,4)}) ${d.slice(4,7)}-${d.slice(7,9)}-${d.slice(9)}`;
  return p;
}

function plural(n, one, few, many) {
  const m10 = n % 10, m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return one;
  if (m10 >= 2 && m10 <= 4 && (m100 < 10 || m100 >= 20)) return few;
  return many;
}

function renderDom() {
  const list = visible();
  const ok = list.filter(isVerified);
  const maybe = list.filter(s => !isVerified(s));

  $("cntOk").textContent = ok.length;
  $("cntMaybe").textContent = maybe.length;
  $("headOk").textContent = ok.length ? `${ok.length}` : "";
  $("headMaybe").textContent = maybe.length ? `${maybe.length}` : "";

  $("cardsOk").innerHTML = ok.length
    ? ok.map(cardHtml).join("")
    : `<div class="empty"><strong>Подтверждённые поставщики не найдены</strong>
         <p>Ниже — возможные поставщики, их контакты нужно проверить вручную.</p></div>`;

  $("cardsMaybe").innerHTML = maybe.length
    ? maybe.map(cardHtml).join("")
    : `<div class="empty"><strong>Возможных поставщиков нет</strong>
         <p>По текущим фильтрам ничего не осталось.</p></div>`;

  const n = state.picked.size;
  $("selN").textContent = `Выбрано ${n}`;
  $("exportBtn").disabled = n === 0;
  $("sendSelectedBtn").disabled = n === 0;
  $("selAll").textContent = n && n >= list.length ? "Снять выбор" : "Выбрать все";
}

function render() {
  // Mail status polling can trigger overlapping updates; a synchronous render avoids aborted transitions.
  renderDom();
}

function toast(text, undo, stop) {
  const el = document.createElement("div");
  el.className = "toast" + (stop ? " stop" : "");
  el.innerHTML = `<span>${text}</span>`;
  if (undo) {
    const b = document.createElement("button");
    b.className = "btn"; b.textContent = "Вернуть";
    b.onclick = () => { undo(); el.remove(); render(); };
    el.appendChild(b);
  }
  $("toasts").appendChild(el);
  setTimeout(() => el.remove(), 7000);
}

document.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-act]");
  if (!btn) return;
  const card = e.target.closest(".card");
  if (!card) return;
  const host = card.dataset.host;
  const s = DATA.suppliers.find(x => x.host === host);
  const act = btn.dataset.act;

  if (act === "pick") {
    state.picked.has(host) ? state.picked.delete(host) : state.picked.add(host);
    render();
  } else if (act === "open") {
    window.open("https://" + host, "_blank", "noopener");
  } else if (act === "black" || act === "irrelevant") {
    state.removed.set(host, act);
    state.picked.delete(host);
    toast(
      act === "black"
        ? `<b>${host}</b> добавлен в чёрный список компании — больше не появится ни в одной заявке.`
        : `<b>${host}</b> помечен нерелевантным для этой заявки.`,
      () => state.removed.delete(host),
      true
    );
    render();
  }
});

$("fRegion").onchange = (e) => { state.region = e.target.value; render(); };
$("fKind").onchange   = (e) => { state.kind = e.target.value; render(); };
$("fRole").onchange   = (e) => { state.role = e.target.value; render(); };
$("fSearch").oninput  = (e) => { state.q = e.target.value.trim(); render(); };

$("selAll").onclick = () => {
  const list = visible();
  if (state.picked.size >= list.length) state.picked.clear();
  else list.forEach(s => state.picked.add(s.host));
  render();
};

$("exportBtn").onclick = () => {
  const rows = DATA.suppliers.filter(s => state.picked.has(s.host));
  $("sheetNote").textContent =
    `${rows.length} ${plural(rows.length, "компания", "компании", "компаний")} · ` +
    `файл Excel со всеми найденными адресами. В прототипе показано содержимое выгрузки.`;
  $("sheetTable").innerHTML =
    `<thead><tr><th>Компания</th><th>Сайт</th><th>Регион</th><th>Роль</th><th>ИНН</th><th>Email</th><th>Телефон</th><th>Закрывает</th></tr></thead>
     <tbody>${rows.map(s => `<tr>
       <td>${cleanTitle(s)}</td>
       <td class="mono">${s.host}</td>
       <td>${s.region || "—"}</td>
       <td>${(s.reg && s.reg.role) || "—"}</td>
       <td class="mono">${s.inn || "—"}</td>
       <td class="mono">${s.emails.map(m => m.e).join("<br>") || "—"}</td>
       <td class="mono">${(s.reg && s.reg.phones.map(fmtPhone).join("<br>")) || "—"}</td>
       <td>${s.covers.map(id => posName[id].replace("Кирпич ", "").replace("Блок ", "")).join(", ") || "—"}</td>
     </tr>`).join("")}</tbody>`;
  $("sheet").classList.add("on");
};
$("sheetClose").onclick = () => $("sheet").classList.remove("on");
$("sheet").onclick = (e) => { if (e.target === $("sheet")) $("sheet").classList.remove("on"); };
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") $("sheet").classList.remove("on");
});

/* Демонстрация фонового поиска — утверждённое требование: пользователь видит
   ход работы, но глубиной не управляет. Кнопок «найти ещё» здесь нет. */
let demo = false, timer = null;
$("demoToggle").onclick = () => {
  demo = !demo;
  $("progress").classList.toggle("on", demo);
  $("demoToggle").textContent = demo ? "Показать результат" : "Показать ход поиска";
  $("statePill").innerHTML = demo
    ? '<span class="dot"></span> Поиск идёт'
    : '<span class="dot"></span> Поиск завершён';
  $("statePill").style.background = demo ? "var(--accent-bg)" : "var(--ok-bg)";
  $("statePill").style.color = demo ? "var(--accent)" : "var(--ok)";
  clearInterval(timer);
  if (demo) {
    let done = 1;
    const total = DATA.positions.length;
    const tick = () => {
      $("progressN").textContent = `Обработано ${done} из ${total} позиций`;
      $("ptrackFill").style.width = (done / total * 100) + "%";
      done = done >= total ? 1 : done + 1;
    };
    tick();
    timer = setInterval(tick, 1800);
  }
};

const mailClient = { csrf: "", authenticated: false, account: null, composerTargets: [] };
const DEFAULT_MAIL_TEMPLATE = `Здравствуйте, {{supplier_name}}!

Наша компания ищет поставщика следующей продукции:

{{request_name}}

{{request_description}}

Просим сообщить:

— стоимость;
— наличие;
— минимальную партию;
— срок поставки;
— условия доставки.

Будем благодарны за коммерческое предложение.

{{sender_name}}
{{company_name}}`;

async function mailApi(path, options = {}) {
  const headers = { ...(options.body ? { "Content-Type": "application/json" } : {}), ...(options.headers || {}) };
  if (mailClient.csrf) headers["X-CSRF-Token"] = mailClient.csrf;
  const response = await fetch(path, { credentials: "same-origin", ...options, headers });
  let payload = {};
  try { payload = await response.json(); } catch (_) { payload = {}; }
  if (!response.ok) throw new Error(payload.error || "Сервер не подтвердил операцию.");
  return payload;
}

function setMailFeedback(id, message, isError = true) {
  const node = $(id);
  if (!node) return;
  node.textContent = message || "";
  node.style.color = isError ? "#b6493e" : "var(--ok)";
}

function openMailModal(id) { $(id).classList.add("on"); }
function closeMailModals() { document.querySelectorAll(".mail-overlay.on").forEach(node => node.classList.remove("on")); }

async function loadMailStatus() {
  if (!mailClient.authenticated) return;
  const status = await mailApi("/api/mail/status");
  mailClient.account = status.connected ? status : null;
  $("mailDisconnectedView").hidden = !!status.connected;
  $("mailConnectedView").hidden = !status.connected;
  if (status.connected) {
    $("connectedMailEmail").textContent = status.email;
    $("connectedMailState").textContent = status.status === "revoked" ? "Требуется переподключение" : "Подключено";
  }
  try {
    const response = await mailApi("/api/mail/request-status?request_id=1043");
    (response.items || []).forEach(item => mailStates.set(item.external_key || item.host, item.status));
    render();
  } catch (_) { /* A supplier has no mail state until the first send. */ }
}

function openSettings() {
  if (!mailClient.authenticated) { openMailModal("mailLoginModal"); return; }
  setMailFeedback("mailSettingsFeedback", "");
  openMailModal("mailSettingsModal");
  loadMailStatus().catch(error => setMailFeedback("mailSettingsFeedback", error.message));
}

function supplierPayload(s) {
  return { name: (s.reg && s.reg.name) || s.title || s.host, email: s.emails[0].e, host: s.host, external_key: s.host };
}

function openComposer(targets) {
  if (!mailClient.account) { openSettings(); setMailFeedback("mailSettingsFeedback", "Подключите рабочую почту, чтобы отправлять запросы поставщикам."); return; }
  mailClient.composerTargets = targets;
  $("composeFrom").value = mailClient.account.email || "";
  $("composeRecipients").replaceChildren(...targets.map(s => {
    const chip = document.createElement("span");
    chip.className = "mail-recipient-chip";
    chip.textContent = s.emails[0].e;
    return chip;
  }));
  $("composeSubject").value = "Запрос коммерческого предложения";
  $("composeBody").value = DEFAULT_MAIL_TEMPLATE;
  $("composeAttachment").value = "";
  setMailFeedback("composerFeedback", "");
  openMailModal("mailComposerModal");
}

function fileAsPayload(file) {
  return new Promise((resolve, reject) => {
    if (!file) { resolve([]); return; }
    if (file.size > 10 * 1024 * 1024) { reject(new Error("Размер одного вложения превышает 10 МБ.")); return; }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Не удалось прочитать вложение."));
    reader.onload = () => resolve([{ filename: file.name, mime_type: file.type || "application/octet-stream", content_base64: String(reader.result).split(",", 2)[1] || "" }]);
    reader.readAsDataURL(file);
  });
}

async function submitComposer(event) {
  event.preventDefault();
  const submit = $("composeSubmit");
  submit.disabled = true;
  setMailFeedback("composerFeedback", "Проверяем письмо и ставим его в очередь…", false);
  try {
    const attachments = await fileAsPayload($("composeAttachment").files[0]);
    const payload = { request_id: 1043, subject: $("composeSubject").value, body: $("composeBody").value, attachments };
    const response = mailClient.composerTargets.length === 1
      ? await mailApi("/api/mail/send", { method: "POST", body: JSON.stringify({ ...payload, supplier: supplierPayload(mailClient.composerTargets[0]) }) })
      : await mailApi("/api/mail/send-bulk", { method: "POST", body: JSON.stringify({ ...payload, suppliers: mailClient.composerTargets.map(supplierPayload) }) });
    mailClient.composerTargets.forEach(s => mailStates.set(s.host, "queued"));
    render();
    closeMailModals();
    toast(`Письма поставлены в очередь: ${response.queued.length}. Каждая компания получит отдельное письмо.`);
    pollMailStatuses();
  } catch (error) {
    setMailFeedback("composerFeedback", error.message);
  } finally {
    submit.disabled = false;
  }
}

function pollMailStatuses(remaining = 8) {
  if (remaining <= 0) return;
  setTimeout(async () => {
    try { await loadMailStatus(); } catch (_) { /* next poll will retry */ }
    pollMailStatuses(remaining - 1);
  }, 1500);
}

$("openMailSettings").onclick = openSettings;
$("mobileMailSettings").onclick = openSettings;
document.querySelectorAll("[data-close-mail]").forEach(button => button.onclick = closeMailModals);
document.querySelectorAll(".mail-overlay").forEach(overlay => overlay.addEventListener("click", event => { if (event.target === overlay) overlay.classList.remove("on"); }));
$("connectYandexBtn").onclick = () => { window.location.href = "/api/mail/yandex/start"; };
$("testMailBtn").onclick = async () => {
  try { setMailFeedback("mailSettingsFeedback", "Проверяем соединение…", false); await mailApi("/api/mail/test", { method: "POST", body: "{}" }); setMailFeedback("mailSettingsFeedback", "Соединение с Яндекс Почтой работает.", false); }
  catch (error) { setMailFeedback("mailSettingsFeedback", error.message); }
};
$("disconnectMailBtn").onclick = async () => {
  if (!confirm("Отключить этот почтовый ящик? Сохранённые токены будут удалены.")) return;
  try { await mailApi("/api/mail/disconnect", { method: "POST", body: "{}" }); mailClient.account = null; await loadMailStatus(); setMailFeedback("mailSettingsFeedback", "Почта отключена.", false); }
  catch (error) { setMailFeedback("mailSettingsFeedback", error.message); }
};
$("mailComposerForm").onsubmit = submitComposer;
$("sendSelectedBtn").onclick = () => {
  const selected = DATA.suppliers.filter(s => state.picked.has(s.host));
  const withoutEmail = selected.filter(s => !s.emails || !s.emails[0] || !s.emails[0].e);
  if (withoutEmail.length) toast(`У ${withoutEmail.length} выбранных поставщиков нет email — они не добавлены в отправку.`, null, true);
  const targets = selected.filter(s => s.emails && s.emails[0] && s.emails[0].e);
  if (targets.length) openComposer(targets);
};

$("loginForm").onsubmit = async (event) => {
  event.preventDefault();
  try {
    const response = await mailApi("/api/auth/login", { method: "POST", body: JSON.stringify({ email: $("loginEmail").value, password: $("loginPassword").value }) });
    mailClient.authenticated = true;
    mailClient.csrf = response.csrf_token || "";
    $("mailLoginModal").classList.remove("on");
    toast("Вы вошли в кабинет снабженца.");
    await loadMailStatus();
  } catch (error) { setMailFeedback("loginFeedback", error.message); }
};

document.addEventListener("click", event => {
  const button = event.target.closest("[data-act=compose]");
  if (!button) return;
  const card = event.target.closest(".card");
  const supplier = card && DATA.suppliers.find(item => item.host === card.dataset.host);
  if (supplier && supplier.emails && supplier.emails[0]) openComposer([supplier]);
});

(async function initMailIntegration() {
  try {
    const response = await mailApi("/api/auth/me");
    if (!response.authenticated) { openMailModal("mailLoginModal"); return; }
    mailClient.authenticated = true;
    mailClient.csrf = response.csrf_token || "";
    await loadMailStatus();
    const query = new URLSearchParams(window.location.search);
    if (query.get("settings") === "mail" || query.get("connected") === "true" || query.get("mail_error")) {
      openSettings();
      if (query.get("connected") === "true") setMailFeedback("mailSettingsFeedback", "Почта успешно подключена.", false);
      if (query.get("mail_error")) setMailFeedback("mailSettingsFeedback", "Не удалось завершить подключение почты. Попробуйте ещё раз.");
    }
  } catch (_) {
    toast("Backend не запущен: для почтовой интеграции запустите python supplier_app.py.", null, true);
  }
})();

renderPositions();
renderFilters();
render();
